"""TOML preservation and known autogenerated runtime-slot refresh."""
import copy
import datetime as dt
import json
import math
import tomllib
from .core import map_path

def scalar(v):
    if isinstance(v,str):return json.dumps(v,ensure_ascii=False)
    if isinstance(v,bool):return "true" if v else "false"
    if isinstance(v,int):return str(v)
    if isinstance(v,float):
        if math.isnan(v):return "nan"
        if math.isinf(v):return "+inf" if v>0 else "-inf"
        return repr(v)
    if isinstance(v,(dt.datetime,dt.date,dt.time)):return v.isoformat()
    if isinstance(v,list):return "["+", ".join(scalar(x) for x in v)+"]"
    if isinstance(v,dict):return "{"+", ".join(json.dumps(k,ensure_ascii=False)+" = "+scalar(x) for k,x in v.items())+"}"
    raise TypeError("Unsupported TOML value")

def dump_toml(data):
    lines=[]
    def table(node,prefix):
        if prefix:lines.extend(["","["+".".join(json.dumps(k,ensure_ascii=False) for k in prefix)+"]"])
        for key,value in node.items():
            if not isinstance(value,dict):lines.append(json.dumps(key,ensure_ascii=False)+" = "+scalar(value))
        for key,value in node.items():
            if isinstance(value,dict):table(value,prefix+[key])
    table(data,[])
    result="\n".join(lines)+"\n"
    if tomllib.loads(result)!=data:raise ValueError("TOML round-trip changed semantics")
    return result

def prepare_config(data,settings,profile):
    data=copy.deepcopy(data)
    profiles=[p["profile"] for p in settings["participants"]]
    prefixes=[(p+r"\AppData\Local\OpenAI\Codex\runtimes").lower()+"\\" for p in profiles]
    def generated(value):
        return isinstance(value,str) and any(value.lower().startswith(p) for p in prefixes)
    notify=data.get("notify")
    if isinstance(notify,list) and notify and generated(notify[0]):del data["notify"]
    servers=data.get("mcp_servers",{})
    if generated(servers.get("node_repl",{}).get("command")):del servers["node_repl"]
    for name in ("openai-primary-runtime","openai-bundled"):
        item=data.get("marketplaces",{}).get(name,{})
        source=item.get("source","").replace("\\","/").lower()
        if "/.cache/codex-runtimes/" in source or "/.tmp/bundled-marketplaces/" in source:
            del data["marketplaces"][name]
    data["cli_auth_credentials_store"]="keyring"
    mappings=settings.get("path_mappings",[])
    for item in data.get("skills",{}).get("config",[]):
        if isinstance(item.get("path"),str):item["path"]=map_path(item["path"],mappings)
    if "projects" in data:
        projects={}
        for key,value in data["projects"].items():
            new=map_path(key,mappings)
            if new in projects and projects[new]!=value:raise ValueError("Project trust-key collision")
            projects[new]=value
        data["projects"]=projects
    protected={"sandbox_mode","approval_policy","permissions","sandbox","windows","prefer_mxc",
               "cli_auth_credentials_store","codex_home"}
    for pointer,replacement in settings.get("ordinary_config_overrides",[]):
        if not pointer or any(str(part).lower() in protected for part in pointer):
            raise ValueError("Permission/auth-storage overrides are not supported")
        node=data
        for part in pointer[:-1]:node=node[part]
        node[pointer[-1]]=replacement
    # Saved task permissions can differ from global config. Never force a mode here.
    dump_toml(data)
    return data
